export interface PastJob {
  id: string;
  title: string | null;
  job_description: string;
  status: string;
  created_at: string;
  resume_count: number;
  jd_analysis_json: any;
  dynamic_weights_json: Record<string, number> | null;
  inbox_email: string | null;
}

export interface Result {
  id: string;
  resume_id: string;
  overall_score: number;
  missing_skills: string[];
  summary: string | null;
  interview_questions: any;
  filename: string;
  file_path: string | null;
  candidate_name: string | null;
  candidate_email?: string | null;
  candidate_phone?: string | null;
  candidate_location?: string | null;
  // Dynamic scoring fields
  hard_fit?: boolean;
  category_scores_json?: Record<string, { score: number; evidence?: any[]; notes?: string }>;
  confidence?: number;
  strengths_json?: string[];
  gaps_json?: string[];
  explanation_json?: { summary?: string; why_ranked_here?: string; key_tradeoffs?: string; matched_preferred?: string[]; missing_preferred?: string[] };
  matched_must_haves?: string[];
  missing_must_haves?: string[];
  scoring_version?: string;
  pending?: boolean;
  parsed_json?: any;
  assigned_to?: string | null;
  source?: string | null;
}

export interface ExistingResume {
  id: string;
  filename: string;
  file_path: string | null;
  candidate_name: string | null;
  created_at: string;
  source?: string | null;
}

type ViewMode = "dashboard" | "my-jobs" | "job-detail" | "new-job";

const ONBOARDING_KEY = "rankora_onboarding_done";

const Index = () => {
  const { user, profile, loading } = useAuth();
  const searchParams = useSearchParams();
  const pathname = usePathname() ?? "/";
  const router = useRouter();

  // Auth wall: server-side proxy already redirects unauthenticated users,
  // but this catches client-side navigation and stale-session edge cases.
  if (!loading && !user) {
    router.replace("/auth");
    return null;
  }

  // Helper to clear all query params (replaces react-router setSearchParams({}, { replace: true }))
  const clearSearchParams = useCallback(() => {
    router.replace(pathname);
  }, [pathname, router]);

  // Show onboarding wizard for first-time users
  const [showOnboarding, setShowOnboarding] = useState(() => {
    if (typeof window === "undefined") return false;
    return !localStorage.getItem(ONBOARDING_KEY);
  });

  const completeOnboarding = useCallback(() => {
    localStorage.setItem(ONBOARDING_KEY, "1");
    setShowOnboarding(false);
  }, []);

  const queryClient = useQueryClient();

  const { data: pastJobs = [], isLoading: loadingPastJobs } = useQuery({
    queryKey: ["pastJobs", user?.id],
    queryFn: async () => {
      const { data: jobs } = await supabase
        .from("jobs")
        .select("id, title, job_description, status, created_at, jd_analysis_json, dynamic_weights_json, inbox_email, resumes(count)")
        .eq("user_id", user!.id)
        .order("created_at", { ascending: false })
        .limit(50);
      if (!jobs) return [];
      return jobs.map((j: any) => ({
        id: j.id,
        title: j.title,
        job_description: j.job_description,
        status: j.status,
        created_at: j.created_at,
        resume_count: j.resumes?.[0]?.count ?? 0,
        jd_analysis_json: j.jd_analysis_json,
        dynamic_weights_json: j.dynamic_weights_json,
        inbox_email: j.inbox_email ?? null,
      })) as PastJob[];
    },
    enabled: !!user,
    staleTime: 2 * 60 * 1000,
  });

  const [selectedJobId, setSelectedJobId] = useState<string | null>(null);
  const [view, setView] = useState<ViewMode>(pathname === "/jobs" ? "my-jobs" : "dashboard");
  const [results, setResults] = useState<Result[]>([]);
  const [existingResumes, setExistingResumes] = useState<ExistingResume[]>([]);
  const [authOpen, setAuthOpen] = useState(false);

  const selectedJob = useMemo(() => pastJobs.find((j) => j.id === selectedJobId) ?? null, [pastJobs, selectedJobId]);

  // Sync view with route path
  useEffect(() => {
    if (pathname === "/jobs") {
      setView("my-jobs");
      setSelectedJobId(null);
    }
  }, [pathname]);

  // Handle URL params for deep linking
  useEffect(() => {
    const jobParam = searchParams?.get("job") ?? null;
    const newParam = searchParams?.get("new") ?? null;

    if (jobParam && user) {
      loadJobData(jobParam);
      clearSearchParams();
    } else if (newParam && user) {
      handleNewJob();
      clearSearchParams();
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [searchParams, user]);

  const loadJobData = async (jobId: string) => {
    setSelectedJobId(jobId);
    setView("job-detail");
    try {
      // Single query for all resume data (was 2 separate queries)
      const { data: allResumes } = await supabase
        .from("resumes")
        .select("id, filename, file_path, candidate_name, created_at, parsed_json, source")
        .eq("job_id", jobId)
        .order("created_at", { ascending: false });

      const resumeData = allResumes ?? [];
      setExistingResumes(resumeData.map((r) => ({
        id: r.id, filename: r.filename, file_path: r.file_path,
        candidate_name: r.candidate_name, created_at: r.created_at,
        source: (r as { source?: string | null }).source ?? null,
      })));

      if (resumeData.length === 0) {
        setResults([]);
        return;
      }

      const resumeIds = resumeData.map((r) => r.id);
      const { data: resultData } = await supabase
        .from("results")
        .select("id, resume_id, overall_score, missing_skills, summary, interview_questions, hard_fit, category_scores_json, confidence, strengths_json, gaps_json, explanation_json, matched_must_haves, missing_must_haves, scoring_version")
        .in("resume_id", resumeIds);

      const resumeMap = new Map(resumeData.map((r) => [r.id, r]));
      const allMerged: Result[] = (resultData ?? []).map((r: any) => {
        const resume = resumeMap.get(r.resume_id);
        const parsed = resume?.parsed_json as any;
        return {
          ...r,
          overall_score: r.overall_score ?? 0,
          missing_skills: r.missing_skills ?? [],
          filename: resume?.filename ?? "Unknown",
          file_path: resume?.file_path ?? null,
          candidate_name: resume?.candidate_name ?? null,

