const TalentPool = () => {
  const router = useRouter();
  const { team } = useTeam();
  const qc = useQueryClient();

  const [search, setSearch] = useState("");
  const [removingId, setRemovingId] = useState<string | null>(null);
  const [notesEntry, setNotesEntry] = useState<PoolEntry | null>(null);
  const [notesText, setNotesText] = useState("");
  const [savingNotes, setSavingNotes] = useState(false);

  const { data: poolEntries = [], isLoading, error, refetch } = useQuery<PoolEntry[]>({
    queryKey: ["talent_pool", team?.id],
    queryFn: async () => {
      if (!team?.id) return [];
      // Fetch pool entries (flat, no joins — avoids FK hint issues)
      const { data: poolData, error: poolError } = await (supabase as any)
        .from("talent_pool")
        .select("id, resume_id, original_job_id, added_by, notes, created_at")
        .eq("team_id", team.id)
        .order("created_at", { ascending: false });

      // Graceful fallback: if table doesn't exist or RLS blocks, return empty
      if (poolError) {
        const code = (poolError as any)?.code;
        // 42P01 = table doesn't exist, PGRST116 = no rows, 42501 = permission denied
        if (code === "42P01" || code === "PGRST116" || code === "42501") return [];
        throw poolError;
      }
      if (!poolData || poolData.length === 0) return [];

      const resumeIds = poolData.map((e: any) => e.resume_id);
      const jobIds = poolData.map((e: any) => e.original_job_id).filter(Boolean);

      // Fetch resumes, jobs, results in parallel
      const [resumesRes, jobsRes, resultsRes] = await Promise.all([
        (supabase as any).from("resumes").select("id, filename, candidate_name, candidate_email, parsed_json, job_id").in("id", resumeIds),
        jobIds.length > 0 ? (supabase as any).from("jobs").select("id, title").in("id", jobIds) : { data: [] },
        (supabase as any).from("results").select("resume_id, overall_score, skill_score, experience_score, authenticity_json").in("resume_id", resumeIds),
      ]);

      const resumeMap: Record<string, any> = {};
      (resumesRes.data ?? []).forEach((r: any) => { resumeMap[r.id] = r; });
      const jobMap: Record<string, any> = {};
      (jobsRes.data ?? []).forEach((j: any) => { jobMap[j.id] = j; });
      const resultMap: Record<string, any> = {};
      (resultsRes.data ?? []).forEach((r: any) => { resultMap[r.resume_id] = r; });

      return poolData.map((e: any) => ({
        ...e,
        resume: resumeMap[e.resume_id] ?? null,
        original_job: e.original_job_id ? (jobMap[e.original_job_id] ?? null) : null,
        result: resultMap[e.resume_id] ?? null,
      }));
    },
    enabled: !!team?.id,
    staleTime: 30_000,
  });

  const handleRemove = async (entryId: string) => {
    setRemovingId(entryId);
    try {
      const { error } = await (supabase as any)
        .from("talent_pool")
        .delete()
        .eq("id", entryId);
      if (error) throw error;
      qc.invalidateQueries({ queryKey: ["talent_pool", team?.id] });
      toast.success("Removed from talent pool");
    } catch {
      toast.error("Failed to remove from pool");
    } finally {
      setRemovingId(null);
    }
  };

  const openNotes = (entry: PoolEntry) => {
    setNotesEntry(entry);
    setNotesText(entry.notes ?? "");
  };

  const handleSaveNotes = async () => {
    if (!notesEntry) return;
    setSavingNotes(true);
    try {
      const { error } = await (supabase as any)
        .from("talent_pool")
        .update({ notes: notesText.trim() || null })
        .eq("id", notesEntry.id);
      if (error) throw error;
      qc.invalidateQueries({ queryKey: ["talent_pool", team?.id] });
      toast.success("Notes saved");

