// ── helpers ──────────────────────────────────────────────────────────────────

function formatDueDate(dateStr: string): string {
  const d = parseISO(dateStr);
  if (isToday(d)) return "Today";
  if (isTomorrow(d)) return "Tomorrow";
  return format(d, "MMM d");
}

// ── priority badge ────────────────────────────────────────────────────────────

const PRIORITY_CONFIG: Record<
  TaskPriority,
  { label: string; className: string }
> = {
  low: { label: "Low", className: "bg-muted text-muted-foreground" },
  medium: { label: "Medium", className: "bg-amber-100 text-amber-700 dark:bg-amber-900/30 dark:text-amber-400" },
  high: { label: "High", className: "bg-red-100 text-red-700 dark:bg-red-900/30 dark:text-red-400" },
};

function PriorityBadge({ priority }: { priority: TaskPriority }) {
  const { label, className } = PRIORITY_CONFIG[priority] ?? PRIORITY_CONFIG.medium;
  return (
    <span
      className={`inline-flex items-center gap-1 text-[10px] font-semibold px-1.5 py-0.5 rounded-full ${className}`}
    >
      <Flag className="h-2.5 w-2.5" />
      {label}
    </span>
  );
}

// ── due date badge ────────────────────────────────────────────────────────────

function DueDateBadge({ dueDate, isDone }: { dueDate: string; isDone: boolean }) {
  const today = new Date();
  const d = parseISO(dueDate);
  const overdue = !isDone && isBefore(d, today);
  const soon = !isDone && !overdue && isBefore(d, addDays(today, 3));

  const className = overdue
    ? "text-red-600 dark:text-red-400"
    : soon
    ? "text-amber-600 dark:text-amber-400"
    : "text-muted-foreground";

  return (
    <span className={`inline-flex items-center gap-1 text-xs ${className}`}>
      <Calendar className="h-3 w-3" />
      {formatDueDate(dueDate)}
    </span>
  );
}

// ── assignee avatar ───────────────────────────────────────────────────────────

function AssigneeAvatar({
  userId,
  members,
}: {
  userId: string;
  members: { user_id: string; email?: string }[];
}) {
  const member = members.find((m) => m.user_id === userId);
  const label = member?.email
    ? member.email[0].toUpperCase()
    : userId.slice(0, 1).toUpperCase();
  const title = member?.email ?? userId;

  return (
    <span
      title={title}
      className="inline-flex items-center justify-center h-5 w-5 rounded-full bg-primary/10 text-primary text-[10px] font-semibold shrink-0"
    >
      {label}
    </span>
  );
}

