// ─── DeadlineBadge ────────────────────────────────────────────────────────────

function DeadlineBadge({ deadline }: { deadline: string | null }) {
  if (!deadline) return <span className="text-muted-foreground text-xs">—</span>;
  try {
    const days = differenceInDays(parseISO(deadline), new Date());
    if (days < 0) {
      return (
        <span className="inline-flex items-center gap-1 text-[11px] font-medium text-red-600 dark:text-red-400">
          <AlertTriangle className="h-3 w-3" />
          {Math.abs(days)}d overdue
        </span>
      );
    }
    if (days === 0) {
      return <Badge variant="destructive" className="text-[10px]">Due today</Badge>;
    }
    if (days <= 3) {
      return <Badge variant="destructive" className="text-[10px]">{days}d left</Badge>;
    }
    if (days <= 7) {
      return (
        <span className="inline-flex items-center gap-1 text-[11px] font-medium text-amber-600 dark:text-amber-400">
          <Clock className="h-3 w-3" />
          {days}d left
        </span>
      );
    }
    return <span className="text-[11px] text-muted-foreground">{fmtDate(deadline)}</span>;
  } catch {
    return <span className="text-muted-foreground text-xs">—</span>;
  }
}

// ─── GuarantyProgress ─────────────────────────────────────────────────────────

function GuarantyProgress({
  startDate,
  guaranteeDays,
  expiresAt,
}: {
  startDate: string | null;
  guaranteeDays: number | null;
  expiresAt: string | null;
}) {
  if (!startDate || !guaranteeDays || !expiresAt) {
    return <span className="text-muted-foreground text-xs">—</span>;
  }
  try {
    const start = parseISO(startDate);
    const end = parseISO(expiresAt);
    const total = differenceInDays(end, start);
    const elapsed = differenceInDays(new Date(), start);
    const daysLeft = differenceInDays(end, new Date());

    if (daysLeft < 0) {
      return <Badge variant="destructive" className="text-[10px]">Expired</Badge>;
    }

    const pct = Math.min(100, Math.max(0, (elapsed / total) * 100));
    const color = pct > 85 ? "bg-red-500" : pct > 60 ? "bg-amber-500" : "bg-emerald-500";

    return (
      <div className="space-y-1 min-w-[100px]">
        <div className="flex items-center justify-between gap-2">
          <span className="text-[10px] text-muted-foreground">{daysLeft}d left</span>
          <span className="text-[10px] text-muted-foreground">{Math.round(pct)}%</span>
        </div>
        <div className="h-1.5 w-full rounded-full bg-muted overflow-hidden">
          <div className={`h-full rounded-full transition-all ${color}`} style={{ width: `${pct}%` }} />
        </div>
      </div>
    );
  } catch {
    return <span className="text-muted-foreground text-xs">—</span>;
  }
}

// ─── StatusBadge ─────────────────────────────────────────────────────────────

function StatusBadge({ status }: { status: string }) {
  const map: Record<string, string> = {
    active: "bg-emerald-100 text-emerald-800 dark:bg-emerald-900/30 dark:text-emerald-400",
    inactive: "bg-gray-100 text-gray-600 dark:bg-gray-800 dark:text-gray-400",
    churned: "bg-red-100 text-red-700 dark:bg-red-900/30 dark:text-red-400",
    open: "bg-blue-100 text-blue-800 dark:bg-blue-900/30 dark:text-blue-400",
    in_progress: "bg-amber-100 text-amber-800 dark:bg-amber-900/30 dark:text-amber-400",
    filled: "bg-emerald-100 text-emerald-800 dark:bg-emerald-900/30 dark:text-emerald-400",
    cancelled: "bg-gray-100 text-gray-600 dark:bg-gray-800 dark:text-gray-400",
    offered: "bg-blue-100 text-blue-800 dark:bg-blue-900/30 dark:text-blue-400",
    accepted: "bg-violet-100 text-violet-800 dark:bg-violet-900/30 dark:text-violet-400",
    started: "bg-emerald-100 text-emerald-800 dark:bg-emerald-900/30 dark:text-emerald-400",
    guarantee: "bg-amber-100 text-amber-800 dark:bg-amber-900/30 dark:text-amber-400",
    completed: "bg-emerald-100 text-emerald-800 dark:bg-emerald-900/30 dark:text-emerald-400",
    fallen_off: "bg-red-100 text-red-700 dark:bg-red-900/30 dark:text-red-400",
    draft: "bg-gray-100 text-gray-600 dark:bg-gray-800 dark:text-gray-400",
    sent: "bg-blue-100 text-blue-800 dark:bg-blue-900/30 dark:text-blue-400",
    paid: "bg-emerald-100 text-emerald-800 dark:bg-emerald-900/30 dark:text-emerald-400",
    overdue: "bg-red-100 text-red-700 dark:bg-red-900/30 dark:text-red-400",
    pending: "bg-amber-100 text-amber-800 dark:bg-amber-900/30 dark:text-amber-400",
    approved: "bg-blue-100 text-blue-800 dark:bg-blue-900/30 dark:text-blue-400",
    high: "bg-red-100 text-red-700 dark:bg-red-900/30 dark:text-red-400",
    medium: "bg-amber-100 text-amber-800 dark:bg-amber-900/30 dark:text-amber-400",
    low: "bg-gray-100 text-gray-600 dark:bg-gray-800 dark:text-gray-400",
  };
  const cls = map[status] ?? "bg-gray-100 text-gray-600";
  const label = status.replace(/_/g, " ");
  return (
    <span className={`inline-flex items-center rounded-full px-2 py-0.5 text-[11px] font-medium capitalize ${cls}`}>
      {label}
    </span>
  );
}

function TableSkeleton({ cols = 5, rows = 4 }: { cols?: number; rows?: number }) {
  return (
    <>
      {Array.from({ length: rows }).map((_, i) => (
        <TableRow key={i}>
          {Array.from({ length: cols }).map((_, j) => (
            <TableCell key={j}>
              <Skeleton className="h-4 w-full" />
            </TableCell>
          ))}
        </TableRow>
      ))}
    </>
  );
}

function EmptyRow({ cols, message }: { cols: number; message: string }) {
  return (
    <TableRow>
      <TableCell colSpan={cols} className="py-12 text-center">
        <div className="flex flex-col items-center gap-2 text-muted-foreground">
          <Building2 className="h-8 w-8 opacity-30" />
          <span className="text-sm">{message}</span>
        </div>
      </TableCell>
    </TableRow>
  );
}

