"use client";

import { useQuery } from "@tanstack/react-query";
import { supabase } from "@/integrations/supabase/client";
import { useAuth } from "@/hooks/useAuth";

type TeamRole = "owner" | "admin" | "member";

export interface TeamMember {
  id: string;
  user_id: string;
  role: TeamRole;
  created_at: string;
  email?: string;
}

export interface TeamInvitation {
  id: string;
  email: string;
  role: TeamRole;
  created_at: string;
  expires_at: string | null;
  accepted_at: string | null;
}

export interface Team {
  id: string;
  name: string;
  owner_user_id: string;
}

export function useTeam() {
  const { user } = useAuth();
  const userId = user?.id;

  const { data, isLoading, error, refetch } = useQuery({
    queryKey: ["team", userId],
    queryFn: async () => {
      if (!userId) return { team: null, members: [], invitations: [], myRole: null };

      // Get user's team membership (prefer owned team, fallback to any team)
      const { data: allMemberships } = await (supabase as any)
        .from("team_members")
        .select("team_id, role")
        .eq("user_id", userId)
        .order("role");

      // Pick the team where user is owner first, otherwise first membership
      const memberships = (allMemberships ?? []) as { team_id: string; role: string }[];
      const tmData = memberships.find((m) => m.role === "owner") ?? memberships[0] ?? null;

      if (!tmData?.team_id) return { team: null, members: [], invitations: [], myRole: null };

      const teamId = tmData.team_id;

      // Fetch team, members, invitations in parallel
      const [teamRes, membersRes, invitationsRes] = await Promise.all([
        (supabase as any).from("teams").select("id, name, owner_user_id").eq("id", teamId).single(),
        (supabase as any).from("team_members").select("id, user_id, role, created_at").eq("team_id", teamId).order("created_at"),
        (supabase as any).from("team_invitations").select("id, email, role, created_at, expires_at, accepted_at").eq("team_id", teamId).is("accepted_at", null).order("created_at", { ascending: false }),
      ]);

      const team: Team | null = teamRes.data ?? null;
      const rawMembers = (membersRes.data ?? []) as TeamMember[];
      const invitations = (invitationsRes.data ?? []) as TeamInvitation[];

      // Augment current user's own record with their email; others show user_id until
      // a profiles.email column is available.
      const members = rawMembers.map((m) => ({
        ...m,
        email: m.user_id === userId ? user?.email ?? undefined : undefined,
      }));

      return { team, members, invitations, myRole: tmData.role as TeamRole };
    },
    enabled: !!userId,
    staleTime: 60_000,
  });

  return {
    team: data?.team ?? null,
    members: data?.members ?? [],
    invitations: data?.invitations ?? [],
    myRole: data?.myRole ?? null,
    isLoading,
    error,
    refetch,
  };
}

"use client";

import { useEffect, useRef, useState } from "react";
import { useQuery, useQueryClient } from "@tanstack/react-query";
import { supabase } from "@/integrations/supabase/client";

export interface ActivityItem {
  id: string;
  team_id: string;
  actor_id: string | null;
  action: string;
  entity_type: string | null;
  entity_id: string | null;
  metadata: Record<string, any>;
  created_at: string;
}

const PAGE_SIZE = 50;

/** Map action strings to the filter tab categories */
const ACTION_FILTER_MAP: Record<string, string[]> = {
  Tasks: ["task_created", "task_completed"],
  Notes: ["note_added"],
  Stages: ["stage_changed"],
  Applications: ["application_received"],
  Members: ["member_joined"],
};

function getActionsForFilter(filter: string): string[] | null {
  if (filter === "All") return null;
  return ACTION_FILTER_MAP[filter] ?? null;
}

export function useActivityFeed(
  teamId: string | null,
  filter: string = "All",
  actorId: string | null = null
) {
  const queryClient = useQueryClient();
  const actions = getActionsForFilter(filter);
  const queryKey = ["activity-feed", teamId, filter, actorId];

  // Cursor for pagination (oldest created_at in current set)
  const [before, setBefore] = useState<string | null>(null);
  const [hasMore, setHasMore] = useState(false);

  // Accumulate pages locally so "Load more" appends
  const [allActivities, setAllActivities] = useState<ActivityItem[]>([]);
  const initialLoaded = useRef(false);

  const { data, isLoading, isFetching, error } = useQuery<ActivityItem[]>({
    queryKey: [...queryKey, before],
    queryFn: async () => {
      if (!teamId) return [];

      let q = (supabase as any)
        .from("activity_log")
        .select("*")
        .eq("team_id", teamId)
        .order("created_at", { ascending: false })
        .limit(PAGE_SIZE + 1); // +1 to detect hasMore

      if (actions && actions.length > 0) {
        q = q.in("action", actions);
      }
      if (actorId) {
        q = q.eq("actor_id", actorId);
      }
      if (before) {
        q = q.lt("created_at", before);
      }

      const { data: rows, error } = await q;
      if (error) throw error;
      return (rows ?? []) as ActivityItem[];
    },
    enabled: !!teamId,
    staleTime: 30_000,
  });

